using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;using Microsoft.Extensions.Hosting;using Microsoft.Extensions.Options;using MongoDB.Driver;using ZosyalMedya.Modules.Comments.Application.Comments;using ZosyalMedya.Modules.Comments.Application.Ports;using ZosyalMedya.Modules.Comments.Contracts;using ZosyalMedya.Modules.Comments.Infrastructure.Configuration;using ZosyalMedya.Modules.Comments.Infrastructure.Persistence.MongoDb;using ZosyalMedya.Modules.Comments.Infrastructure.Persistence.PostgreSql;
namespace ZosyalMedya.Modules.Comments.Infrastructure;
public static class DependencyInjection{public static IServiceCollection AddCommentsModule(this IServiceCollection s,IConfiguration c){s.AddOptions<CommentsPersistenceOptions>().Bind(c.GetSection(CommentsPersistenceOptions.SectionName)).ValidateDataAnnotations().ValidateOnStart();var o=c.GetSection(CommentsPersistenceOptions.SectionName).Get<CommentsPersistenceOptions>()??throw new InvalidOperationException("Comments persistence configuration is missing.");if(o.Provider==CommentsPersistenceProvider.PostgreSql){s.AddDbContext<CommentsDbContext>(x=>x.UseNpgsql(o.PostgreSqlConnectionString));s.AddScoped<ICommentRepository,PostgreSqlCommentRepository>();}else{s.AddSingleton(_=>new CommentsMongoDatabase(new MongoClient(o.MongoConnectionString).GetDatabase(o.MongoDatabaseName)));s.AddScoped(sp=>new MongoCommentRepository(sp.GetRequiredService<CommentsMongoDatabase>().Database));s.AddScoped<ICommentRepository>(sp=>sp.GetRequiredService<MongoCommentRepository>());}s.AddScoped<CreateCommentHandler>();s.AddScoped<ListCommentsHandler>();s.AddScoped<ChangeCommentHandler>();s.AddScoped<ICommentsModule,CommentsModule>();s.AddHostedService<Initializer>();return s;}}
internal sealed record CommentsMongoDatabase(IMongoDatabase Database);internal sealed class Initializer(IServiceProvider p,IOptions<CommentsPersistenceOptions>o):IHostedService{public async Task StartAsync(CancellationToken t){await using var s=p.CreateAsyncScope();if(o.Value.Provider==CommentsPersistenceProvider.PostgreSql)await s.ServiceProvider.GetRequiredService<CommentsDbContext>().Database.MigrateAsync(t);else await s.ServiceProvider.GetRequiredService<MongoCommentRepository>().EnsureIndexesAsync(t);}public Task StopAsync(CancellationToken t)=>Task.CompletedTask;}
